name: Comment artifacts

on:
  workflow_run:
    workflows: ["test-build.yml"]
    types:
      - completed

permissions:
  contents: read
  pull-requests: write
  actions: read

jobs:
  comment-artifacts:
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Post ISO artifact links to PR
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const run = context.payload.workflow_run;

            // Identify the PR that contains this commit
            const headOwner = run.head_repository.owner.login;
            const headBranch = run.head_branch;
            const pulls = await github.pulls.list({
              owner,
              repo,
              head: `${headOwner}:${headBranch}`
            });

            if (pulls.data.length === 0) {
              console.log('No PR found for this commit.');
              return;
            }
            const pr = pulls.data[0];

            // Retrieve artifacts for the repository
            const artifacts = await github.actions.listArtifactsForRepo({
              owner,
              repo,
              per_page: 100
            });

            // Filter ISO artifacts
            const isoArtifacts = artifacts.data.artifacts.filter(a => a.name.includes('iso'));
            if (isoArtifacts.length === 0) {
              console.log('No ISO artifacts found.');
              return;
            }

            // Build comment body
            const bodyLines = isoArtifacts.map(a => `- [${a.name}](${a.archive_download_url})`);
            const body = 'ISO artifact download links:\n' + bodyLines.join('\n');

            // Create comment on the PR
            await github.issues.createComment({
              owner,
              repo,
              issue_number: pr.number,
              body
            });
